abstract contract ERC721TokenReceiver {
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external virtual returns (bytes4) {
        return bytes4(0xdeadbeef);
    }
}

function initialize(
    address _baseToken,
    address _nft,
    uint128 _virtualBaseTokenReserves,
    uint128 _virtualNftReserves,
    uint56 _changeFee,
    uint16 _feeRate,
    bytes32 _merkleRoot,
    bool _useStolenNftOracle,
    bool _payRoyalties
) public {

    if (initialized) revert AlreadyInitialized();

    if (_feeRate > 5_000) revert FeeRateTooHigh();

    baseToken = address(0);
    nft = _nft;
    virtualBaseTokenReserves = _virtualBaseTokenReserves;
    virtualNftReserves = _virtualNftReserves;
    changeFee = _changeFee;
    feeRate = _feeRate;
    merkleRoot = _merkleRoot;
    useStolenNftOracle = _useStolenNftOracle;
    payRoyalties = _payRoyalties;

    initialized = true;

    emit Initialize(
        _baseToken,
        _nft,
        _virtualBaseTokenReserves,
        _virtualNftReserves,
        _changeFee,
        _feeRate,
        _merkleRoot,
        _useStolenNftOracle,
        _payRoyalties
    );
}

